package com.hrcoresystem.hrcore_api.modules.tenant.positions.application.service;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.domain.model.TenantSettingKeys; import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.domain.repository.TenantSettingRepository; import org.springframework.stereotype.Service;
@Service public class PositionCurrencyResolver { private final TenantSettingRepository repo; public PositionCurrencyResolver(TenantSettingRepository r){repo=r;} public String resolve(String value, boolean hasSalary){String v=value==null?null:value.trim().toUpperCase(); if(v==null&&hasSalary) v=repo.findByKey(TenantSettingKeys.COMPANY_CURRENCY).map(s->s.settingValue()).orElse(null); if(v==null&&hasSalary) throw new com.hrcoresystem.hrcore_api.common.exception.BusinessException("Debe configurar la moneda empresarial para cargos con rango salarial"); if(v!=null) try{java.util.Currency.getInstance(v);}catch(Exception e){throw new com.hrcoresystem.hrcore_api.common.exception.BusinessException("La moneda del cargo no es válida");} return v;} }
